package me.chanjar.weixin.common.util.fs;

import java.io.IOException;
import java.io.InputStream;
import java.util.Base64;

/**
 * Standalone regression test for the available() bug in FileUtils.imageToBase64ByStream.
 * This test does NOT depend on TestNG/AssertJ and can be run directly.
 */
public class FileUtilsPartialAvailableTest {

  public static void main(String[] args) {
    testImageToBase64ByStreamWithPartialAvailable();
  }

  public static void testImageToBase64ByStreamWithPartialAvailable() {
    byte[] originalData = "HelloWorldThisIsSomeTestData".getBytes();
    Base64.Encoder encoder = Base64.getEncoder();
    String expectedBase64 = encoder.encodeToString(originalData);

    // Create a stream where available() returns less than actual data length,
    // but read() can still read the full data.
    InputStream partialAvailableStream = new InputStream() {
      private byte[] data = originalData;
      private int pos = 0;

      @Override
      public int read() throws IOException {
        if (pos >= data.length) {
          return -1;
        }
        return data[pos++] & 0xFF;
      }

      @Override
      public int read(byte[] buf) throws IOException {
        if (pos >= data.length) {
          return -1;
        }
        int actualRead = Math.min(buf.length, data.length - pos);
        System.arraycopy(data, pos, buf, 0, actualRead);
        pos += actualRead;
        return actualRead;
      }

      @Override
      public int available() throws IOException {
        // Bug trigger: available() returns only 5 bytes even though the full
        // data is much longer. This simulates network streams where available()
        // returns partial data.
        return Math.min(5, data.length - pos);
      }
    };

    String actualBase64 = FileUtils.imageToBase64ByStream(partialAvailableStream);

    // The method should encode the FULL data, not just what available() reports.
    if (!expectedBase64.equals(actualBase64)) {
      System.err.println("FAIL: Expected base64: " + expectedBase64);
      System.err.println("FAIL: Actual base64:   " + actualBase64);
      throw new AssertionError("imageToBase64ByStream truncated data: expected " 
          + expectedBase64.length() + " chars but got " 
          + (actualBase64 != null ? actualBase64.length() : "null"));
    }
    System.out.println("PASS: Full data encoded correctly.");
  }
}

