package com.github.binarywang.wxpay.v3.util;

import java.security.Provider;
import java.security.Security;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Test for AesUtils HMACSHA256 method - verifies that exceptions are properly
 * propagated rather than silently swallowed by returning null.
 * 
 * This test removes all SecurityProviders to force Mac.getInstance to throw,
 * triggering the catch block in AesUtils.HMACSHA256.
 * 
 * Run with:
 * javac -d /tmp/classes -cp <commons-lang3.jar> AesUtils.java
 * javac -d /tmp/test-classes -cp /tmp/classes:<commons-lang3.jar> AesUtilsHmacSha256Test.java
 * java -cp /tmp/test-classes:/tmp/classes:<commons-lang3.jar> com.github.binarywang.wxpay.v3.util.AesUtilsHmacSha256Test
 */
public class AesUtilsHmacSha256Test {

  private static int failures = 0;
  private static int tests = 0;
  private static int passed = 0;

  private List<Provider> savedProviders = new ArrayList<>();

  /**
   * Setup: save all providers before each test.
   */
  private void setUp() {
    savedProviders = new ArrayList<>();
    for (Provider p : Security.getProviders()) {
      savedProviders.add(p);
    }
  }

  /**
   * Cleanup: restore all providers after each test.
   */
  private void tearDown() {
    for (Provider p : Security.getProviders()) {
      Security.removeProvider(p.getName());
    }
    for (Provider p : savedProviders) {
      Security.insertProviderAt(p, 1);
    }
  }

  /**
   * Disable crypto by removing all SecurityProviders.
   */
  private void disableCryptoProviders() {
    for (Provider p : savedProviders) {
      Security.removeProvider(p.getName());
    }
  }

  /**
   * Test that HMACSHA256 throws an exception when Mac operations fail,
   * rather than silently returning null.
   * 
   * Correct behavior: should throw RuntimeException wrapping the original exception.
   * Buggy behavior: catches all exceptions, prints stack trace, returns null.
   * 
   * This test FAILS on buggy code (null returned) and PASSES on fixed code (exception thrown).
   */
  public void testHmacSha256ShouldThrowNotReturnNullOnCryptoFailure() {
    tests++;
    setUp();

    try {
      disableCryptoProviders();

      boolean exceptionWasThrown = false;
      String returnedValue = null;
      try {
        String data = "test data";
        String key = "test key";

        returnedValue = AesUtils.HMACSHA256(data, key);

        // If we reach here, the method returned a value instead of throwing
        // This is the BUGGY behavior - it catches the exception and returns null
      } catch (RuntimeException e) {
        // CORRECT behavior: exception propagated to caller
        exceptionWasThrown = true;
      }

      // Assert that an exception WAS thrown (correct behavior)
      // This will FAIL on buggy code because null is returned, not exception
      if (!exceptionWasThrown) {
        System.err.println("FAIL: testHmacSha256ShouldThrowNotReturnNullOnCryptoFailure");
        System.err.println("  HMACSHA256 returned '" + returnedValue + "' instead of throwing an exception.");
        System.err.println("  Returning null silently masks cryptographic failures which is a security risk.");
        failures++;
        return;
      }
      passed++;
    } finally {
      tearDown();
    }
  }

  /**
   * Test normal operation: HMACSHA256 should produce a non-null, valid hex string
   * when given valid inputs.
   */
  public void testHmacSha256NormalOperation() {
    tests++;
    setUp();

    try {
      String data = "test data";
      String key = "test key";

      String result = AesUtils.HMACSHA256(data, key);

      if (result == null) {
        System.err.println("FAIL: testHmacSha256NormalOperation - HMACSHA256 returned null with valid inputs");
        failures++;
        return;
      }
      if (result.length() != 64) {
        System.err.println("FAIL: testHmacSha256NormalOperation - expected 64 hex chars, got " + result.length());
        failures++;
        return;
      }
      if (!result.equals(result.toUpperCase())) {
        System.err.println("FAIL: testHmacSha256NormalOperation - expected uppercase hex");
        failures++;
        return;
      }
      passed++;
    } finally {
      tearDown();
    }
  }

  /**
   * Test that createSign also throws when the underlying HMACSHA256 fails.
   */
  public void testCreateSignShouldThrowNotReturnNullOnCryptoFailure() {
    tests++;
    setUp();

    try {
      disableCryptoProviders();

      boolean exceptionWasThrown = false;
      String returnedValue = null;
      try {
        Map<String, String> params = new HashMap<>();
        params.put("appid", "wx123");
        params.put("mch_id", "merchant123");
        params.put("nonce_str", "nonce123");

        returnedValue = AesUtils.createSign(params, "mchKey123");

        // Should not reach here - should have thrown exception
      } catch (RuntimeException e) {
        // CORRECT behavior: exception propagated to caller
        exceptionWasThrown = true;
      }

      if (!exceptionWasThrown) {
        System.err.println("FAIL: testCreateSignShouldThrowNotReturnNullOnCryptoFailure");
        System.err.println("  createSign returned '" + returnedValue + "' instead of throwing an exception.");
        failures++;
        return;
      }
      passed++;
    } finally {
      tearDown();
    }
  }

  public static void main(String[] args) {
    System.out.println("Running AesUtils HMACSHA256 tests...");

    AesUtilsHmacSha256Test test = new AesUtilsHmacSha256Test();

    test.testHmacSha256NormalOperation();
    test.testHmacSha256ShouldThrowNotReturnNullOnCryptoFailure();
    test.testCreateSignShouldThrowNotReturnNullOnCryptoFailure();

    System.out.println();
    System.out.println("Results: " + tests + " tests, " + passed + " passed, " + failures + " failures");

    if (failures > 0) {
      System.out.println("TESTS FAILED - Bug confirmed: HMACSHA256 silently returns null instead of throwing exceptions");
      System.exit(1);
    } else {
      System.out.println("ALL TESTS PASSED");
      System.exit(0);
    }
  }
}

