package me.chanjar.weixin.common.util.crypto;

import org.testng.annotations.Test;

import static org.testng.Assert.*;

/**
 * Tests for PKCS7Encoder edge cases.
 */
public class PKCS7EncoderTest {

  @Test
  public void decodeEmptyArrayShouldNotThrowArrayIndexOutOfBoundsException() {
    // An empty byte array should be handled gracefully, not cause an AIOOBE.
    // The correct behavior: return an empty byte array for empty input.
    try {
      byte[] result = PKCS7Encoder.decode(new byte[0]);
      // If it doesn't throw, it should return an empty array
      assertNotNull(result);
      assertEquals(result.length, 0);
    } catch (ArrayIndexOutOfBoundsException e) {
      fail("PKCS7Encoder.decode(new byte[0]) should not throw ArrayIndexOutOfBoundsException, "
        + "but should return an empty array or throw a meaningful exception");
    }
  }
}

