 *
 * @author <a href="https://github.com/binarywang">Binary Wang</a>
 */
public class SignUtilsTest {
  /**
   * Test create sign.
   *
   * @throws Exception the exception
   */
  @Test
  public void testCreateSign() throws Exception {
