package me.chanjar.weixin.common.util.locks;

import org.mockito.Mockito;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.ValueOperations;
import org.testng.Assert;
import org.testng.annotations.BeforeMethod;
import org.testng.annotations.Test;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * 测试 RedisTemplateSimpleDistributedLock 的线程中断处理行为
 *
 * @author GitHub Copilot
 */
public class RedisTemplateSimpleDistributedLockInterruptTest {

  private StringRedisTemplate mockRedisTemplate;
  private ValueOperations<String, String> mockValueOps;
  private RedisTemplateSimpleDistributedLock lock;

  @BeforeMethod
  @SuppressWarnings("unchecked")
  public void setUp() {
    mockRedisTemplate = Mockito.mock(StringRedisTemplate.class);
    mockValueOps = Mockito.mock(ValueOperations.class);
    Mockito.when(mockRedisTemplate.opsForValue()).thenReturn(mockValueOps);
    lock = new RedisTemplateSimpleDistributedLock(mockRedisTemplate, "test_interrupt_lock", 60000);
  }

  /**
   * 测试 lock() 在 Thread.sleep 被中断时应恢复线程中断标志
   * <p>
   * 修复前：InterruptedException 被忽略（// Ignore），线程中断标志丢失
   * 修复后：调用 Thread.currentThread().interrupt() 恢复中断标志
   * </p>
   */
  @Test(description = "lock() 方法在中断时应恢复线程中断标志")
  public void testLockRestoresInterruptedFlagAfterSleepInterruption() throws InterruptedException {
    AtomicBoolean interruptedFlagAfterLock = new AtomicBoolean(false);

    // 第一次 setIfAbsent 返回 false（模拟锁被占用），第二次返回 true（模拟锁释放）
    Mockito.when(mockValueOps.setIfAbsent(Mockito.anyString(), Mockito.anyString(),
        Mockito.anyLong(), Mockito.any(TimeUnit.class)))
      .thenReturn(false)
      .thenReturn(true);
    // get() 返回不同的值，确保不走可重入路径
    Mockito.when(mockValueOps.get(Mockito.anyString())).thenReturn("other-value");

    Thread testThread = new Thread(() -> {
      // 设置中断标志
      Thread.currentThread().interrupt();
      // 调用 lock()，第一次 tryLock 失败，sleep 会因中断标志立即抛出 InterruptedException
      lock.lock();
      interruptedFlagAfterLock.set(Thread.currentThread().isInterrupted());
    });

    testThread.start();
    testThread.join(5000);

    // 线程应该已经完成（不会永远阻塞）
    Assert.assertFalse(testThread.isAlive(), "线程应该已完成");
    // 关键验证：中断标志应被恢复（而非被忽略丢失）
    Assert.assertTrue(interruptedFlagAfterLock.get(), "lock()执行后线程中断标志应被恢复");
  }

  /**
   * 测试 tryLock() 在 Redis 正常响应时的基本行为
   */
  @Test(description = "tryLock() 成功获取锁时应返回 true")
  public void testTryLockSuccessfully() {
    Mockito.when(mockValueOps.setIfAbsent(Mockito.anyString(), Mockito.anyString(),
        Mockito.anyLong(), Mockito.any(TimeUnit.class)))
      .thenReturn(true);

    boolean result = lock.tryLock();

    Assert.assertTrue(result, "应成功获取锁");
    Assert.assertNotNull(lock.getLockSecretValue(), "锁值不应为null");
  }

  /**
   * 测试 tryLock() 在锁已被其他线程持有时应返回 false
   */
  @Test(description = "锁被占用时 tryLock() 应返回 false")
  public void testTryLockWhenLockHeld() {
    Mockito.when(mockValueOps.setIfAbsent(Mockito.anyString(), Mockito.anyString(),
        Mockito.anyLong(), Mockito.any(TimeUnit.class)))
      .thenReturn(false);
    Mockito.when(mockValueOps.get(Mockito.anyString())).thenReturn("other-lock-value");

    boolean result = lock.tryLock();

    Assert.assertFalse(result, "锁被占用时应返回false");
  }

  /**
   * Test TOCTOU race condition in tryLock().
   * <p>
   * Scenario: setIfAbsent returns false (lock held by someone), but between setIfAbsent
   * and the subsequent get(), the lock has expired and been re-acquired by another thread
   * that happens to hold the same value (e.g., from a previous lock acquisition by the
   * same thread, or another thread with coincidentally the same UUID).
   * <p>
   * Bug: The code does a separate get(key) and compares with local value, which can
   * incorrectly return true even though setIfAbsent proved we don't hold the lock.
   * <p>
   * Fix: If setIfAbsent returns false, we should always return false, because setIfAbsent
   * atomically proved the key already existed at that moment.
   */
  @Test(description = "TOCTOU race: setIfAbsent=false but get returns same value should still return false")
  public void testTryLockTOCTOURaceShouldNotClaimOwnershipWhenSetIfAbsentFailed() {
    // First call: acquire a "previous" lock value by successfully calling tryLock
    Mockito.when(mockValueOps.setIfAbsent(Mockito.anyString(), Mockito.anyString(),
        Mockito.anyLong(), Mockito.any(TimeUnit.class)))
      .thenReturn(true);

    boolean firstAcquire = lock.tryLock();
    Assert.assertTrue(firstAcquire, "First tryLock should succeed");
    String ourValue = lock.getLockSecretValue();
    Assert.assertNotNull(ourValue, "Should have a lock value");

    // Now simulate unlock without actually removing ThreadLocal
    // (simulating a reentrant scenario where the lock was externally expired)
    // We manually clear the Redis state but keep ThreadLocal value
    // Reset the lock for the second scenario
    lock.unlock();

    // Reset mocks for the TOCTOU scenario
    Mockito.reset(mockValueOps);

    // Now simulate the TOCTOU race:
    // 1. setIfAbsent returns false (someone else holds the lock at that moment)
    // 2. Between setIfAbsent and get, the lock expires and another thread 
    //    acquires it with the SAME value (possible in real distributed systems 
    //    if value is deterministic or from a small space)
    // The key insight: since we unlocked, ThreadLocal is cleared. 
    // We need a lock instance that still has the ThreadLocal value.

    // Create a new lock instance for the test
    RedisTemplateSimpleDistributedLock newLock = new RedisTemplateSimpleDistributedLock(
        mockRedisTemplate, "test_toc_tou_lock", 60000);

    // Step 1: First successfully acquire to populate ThreadLocal
    Mockito.when(mockValueOps.setIfAbsent(Mockito.anyString(), Mockito.anyString(),
        Mockito.anyLong(), Mockito.any(TimeUnit.class)))
      .thenReturn(true);
    Mockito.when(mockRedisTemplate.opsForValue()).thenReturn(mockValueOps);

    // Need a new lock bound to our mock
    RedisTemplateSimpleDistributedLock testLock = new RedisTemplateSimpleDistributedLock(
        mockRedisTemplate, "test_toc_tou_lock", 60000);

    // First successful acquire to get a ThreadLocal value
    Mockito.when(mockValueOps.setIfAbsent(Mockito.anyString(), Mockito.anyString(),
        Mockito.anyLong(), Mockito.any(TimeUnit.class)))
      .thenReturn(true);
    boolean acquired = testLock.tryLock();
    Assert.assertTrue(acquired, "First acquire should succeed");

    String testValue = testLock.getLockSecretValue();
    Assert.assertNotNull(testValue);

    // Don't unlock - keep ThreadLocal value. But simulate the Redis key 
    // being held by another thread (e.g., via external Redis operation).

    // Reset and set up the TOCTOU scenario:
    Mockito.reset(mockValueOps);
    Mockito.when(mockRedisTemplate.opsForValue()).thenReturn(mockValueOps);

    // setIfAbsent returns false -> the lock is held by someone else
    Mockito.when(mockValueOps.setIfAbsent(Mockito.anyString(), Mockito.anyString(),
        Mockito.anyLong(), Mockito.any(TimeUnit.class)))
      .thenReturn(false);

    // get returns the SAME value as our ThreadLocal -> simulating the race window
    // where between setIfAbsent and get, the original holder released and another
    // thread with the same value acquired it
    Mockito.when(mockValueOps.get(Mockito.anyString())).thenReturn(testValue);

    // BUG: tryLock should return false because setIfAbsent already told us
    // the key was occupied. The fact that get() returns our value is irrelevant
    // - that's a TOCTOU artifact, not proof of ownership.
    // CORRECT behavior: return false since setIfAbsent failed.
    boolean result = testLock.tryLock();

    Assert.assertFalse(result,
        "当 setIfAbsent 返回 false 时，即使 get 返回相同的值，也应返回 false。" +
        "这是 TOCTOU 竞争条件：setIfAbsent 原子性地证明了键已被占用。" +
        "当前代码错误地比较 get 结果与本地值，导致线程错误地认为自己持有锁。");
  }
}

